(function(root){
function createCeoReport(s,type){const m=calculateQuarter(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),cash=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:0}),pct=n=>n===null?'N/A':n.toFixed(1)+'%',title=type==='clinical'?'Clinical impact':'Financial impact';const notice='<div class="notice"><b>HYPOTHETICAL SCENARIO - ALL VALUES INVENTED.</b> Assumed rollout in July 2026. Not measured results, forecasts or proof of CDS causality. Separate from the application patient registry.</div>';const head=(section,n,total)=>`<header><div><span class="eyebrow">FN CLINICAL CDS / CEO BRIEF</span><h1>${title} <span>${section}</span></h1></div><div class="pageid">${n} / ${total}</div></header><div class="period">${esc(s.baseline)} <b>versus</b> ${esc(s.followup)} · ${esc(s.currency)}</div>${notice}`;const table=(cols,rows,widths)=>`<table>${widths?'<colgroup>'+widths.map(w=>'<col style="width:'+w+'%">').join('')+'</colgroup>':''}<thead><tr>${cols.map(c=>'<th>'+c+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')}</tbody></table>`;const cards=rows=>'<div class="tiles">'+rows.map(([h,v,n])=>`<div><small>${h}</small><strong>${v}</strong><p>${n}</p></div>`).join('')+'</div>';const foot='<footer>Decision-support prototype · Synthetic business case · Values must be replaced and validated before investment or clinical claims.</footer>';let pages=[];
if(type==='financial'){
pages.push(head('Investment summary',1,3)+cards([['FIRST-PASS NON-ACCEPTANCE',pct(m.beforeRate)+' → '+pct(m.afterRate),m.beforeRejected+' → '+m.afterRejected+' / '+s.claims+' claims'],['MODELED REVENUE UPLIFT',cash(m.uplift),pct(m.revenueGrowth)+' at fixed billing volume/value'],['FIRST-QUARTER NET',cash(m.net),'After '+cash(m.cost)+' implementation + operation'],['MODELED ROI',pct(m.roi),m.paybackMonths===null?'No positive payback':m.paybackMonths.toFixed(2)+' months simple modeled payback']])+`<h2>Revenue bridge (${esc(s.currency)})</h2>`+table(['Item','Baseline Q2','Post Q3'],[['Gross billed: '+s.claims+' claims × '+cash(s.claimValue),cash(m.grossBilled),cash(m.grossBilled)],['Initially non-accepted claim value',cash(m.rejectedValueBefore),cash(m.rejectedValueAfter)],['Modeled later recovery ('+pct(s.recoveryFraction*100)+')',cash(m.modeledRecoveryBefore),cash(m.modeledRecoveryAfter)],['<b>Modeled eventual collectible revenue</b>','<b>'+cash(m.revenueBefore)+'</b>','<b>'+cash(m.revenueAfter)+'</b>']],[54,23,23])+`<p class="method">Not actual quarter cash collections. Accepted claims are assumed fully collectible. Equal ${pct(s.recoveryFraction*100)} later-recovery assumptions apply in both quarters. Reduced rejected value is not added again as revenue. Contractual discounts, taxes, financing and disruption are not modeled.</p>`+foot);
pages.push(head('Claims by primary reason',2,3)+`<h2>Mutually exclusive reasons: one primary reason per unique claim</h2>`+table(['Primary reason / stage','Q2 count / rate','Q3 count / rate','Relative reduction','Assumed workflow contribution'],s.reasons.map(r=>['<b>'+esc(r.name)+'</b><small>'+esc(r.stage)+'</small>',r.before+' / '+pct(100*r.before/s.claims),r.after+' / '+pct(100*r.after/s.claims),r.before?pct(100*(r.before-r.after)/r.before):'N/A',esc(r.mechanism)]),[23,13,13,12,39])+`<div class="summaryline"><b>Total combined non-acceptance:</b> ${m.beforeRejected}/${s.claims} (${pct(m.beforeRate)}) → ${m.afterRejected}/${s.claims} (${pct(m.afterRate)}); ${m.rateReductionPP.toFixed(1)} percentage points lower; ${pct(m.relativeReduction)} relative reduction.</div><p>Technical validation returns: ${m.technicalBefore} → ${m.technicalAfter}. Adjudicated payer denials: ${m.denialsBefore} → ${m.denialsAfter}. The combined headline must not be described as technical rejection alone.</p><p class="method">This assumes a CDS + revenue-cycle workflow bundle. Coding validation, eligibility, payer authorization and billing submission services are not connected in the prototype. Contribution mechanisms are hypotheses, not proven CDS effects.</p>`+foot);
pages.push(head('Costs, sensitivity and capacity',3,3)+`<h2>Investment assumptions (${esc(s.currency)})</h2>`+table(['Item','Value','Interpretation'],[['One-time implementation',cash(s.upfront),'Assumed upfront cost'],['Quarter operating cost',cash(s.quarterOperating),'Assumed recurring cost'],['Realized share of modeled uplift',pct(s.realization*100),'Editable assumption; attribution unproven'],['First-quarter net benefit',cash(m.net),'Realized uplift minus upfront and quarter operating cost'],['Recurring-quarter net benefit',cash(m.recurringNet),'Does not repeat the upfront implementation cost'],['First-quarter break-even realization',pct(m.breakEvenRealization),'Required share of modeled uplift under this cost model']],[39,19,42])+`<h2>Sensitivity: benefit may be lower than assumed</h2>`+table(['Realization','Incremental revenue','First-quarter net','ROI'],[.25,.5,1].map(f=>{const x=calculateQuarter({...s,realization:f});return[pct(f*100),cash(x.realized),cash(x.net),pct(x.roi)]}),[25,25,25,25])+`<p class="method">Simple payback assumes even monthly uplift and operating cost. Model outcome is not guaranteed. ${m.bedDaysReleased} released bed-days × ${cash(s.variableBedDay)} = ${cash(m.bedResourceValue)} resource value; claims rework value ${cash(m.reworkResourceValue)}. Total ${cash(m.capacityValue)} capacity value is excluded from cash ROI. No additional overlapping sepsis/ICU savings are added.</p>`+foot);
}else{const summary=['antibiotic','sepsis','icu'].map(k=>m.clinical.find(r=>r.key===k));pages.push(head('Process performance',1,2)+cards(summary.map(r=>[esc(r.label),pct(r.beforeRate)+' → '+pct(r.afterRate),r.before+'/'+r.denom+' → '+r.after+'/'+r.denom]).concat([['INPATIENT LENGTH OF STAY',m.losBefore.toFixed(1)+' → '+m.losAfter.toFixed(1)+' days',s.inpatients+' admissions in each quarter']]))+`<h2>Process measures</h2>`+clinicalTable(m.clinical.slice(0,6))+`<p class="method">Hypothetical cohorts: ${s.cohort} eligible adult FN episodes each quarter, 120 high-risk / 80 low-risk, ${s.inpatients} admissions / ${s.discharged} discharges. Same eligibility and exclusion definitions. Counts are independent of current episode records. Cultures must not delay antibiotic treatment.</p>`+foot);
pages.push(head('Outcomes and interpretation',2,2)+`<h2>Hypothetical outcomes - not measured treatment effects</h2>`+clinicalTable(m.clinical.slice(6))+`<div class="summaryline"><b>Inpatient resource use:</b> ${s.bedDaysBefore} → ${s.bedDaysAfter} bed-days across ${s.inpatients} admissions each quarter; mean LOS ${m.losBefore.toFixed(1)} → ${m.losAfter.toFixed(1)} days; ${m.bedDaysReleased} fewer modeled bed-days.</div><p class="method">Sepsis and shock require consistent clinical adjudication; lactate alone does not diagnose shock. Outcomes may overlap and are not summed as independent benefits. Readmission uses ${s.discharged} discharged patients with complete fictional 30-day follow-up. Small invented mortality counts do not support significance or causal claims. Improved recognition can initially increase recorded sepsis. A real evaluation needs comparable case mix, observation windows, outcome definitions and assessment of concurrent changes.</p>`+foot);
}
function clinicalTable(rows){return table(['Measure','Q2 numerator / denominator','Q3 numerator / denominator','Change (post − pre)','Definition'],rows.map(r=>['<b>'+esc(r.label)+'</b>',r.before+'/'+r.denom+'<small>'+pct(r.beforeRate)+'</small>',r.after+'/'+r.denom+'<small>'+pct(r.afterRate)+'</small>',(r.changePP>0?'+':'')+r.changePP.toFixed(1)+' pp',esc(r.definition)]),[23,16,16,13,32])}
return `<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FN CEO ${title} - HYPOTHETICAL</title><style>@page{size:A4 landscape;margin:11mm 12mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#193b43;margin:0;font-size:10pt;line-height:1.35;background:#e9efec}.toolbar{padding:15px 24px;position:sticky;top:0;background:#102e38;color:white;display:flex;justify-content:space-between;align-items:center;z-index:2}.toolbar button{background:white;color:#193b43;border:0;padding:10px 16px;border-radius:6px;cursor:pointer}.page{width:273mm;max-width:none;min-height:180mm;background:white;margin:18px auto;padding:10mm;box-shadow:0 4px 25px #1232;break-after:page;page-break-after:always}.page:last-child{break-after:auto;page-break-after:auto}header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #167a6e;padding-bottom:8px;margin-bottom:8px}.eyebrow{font-size:8pt;letter-spacing:1.2px;color:#5e787c}h1{font-size:20pt;margin:4px 0;line-height:1.15}h1 span{font-size:12pt;display:block;font-weight:normal;margin-top:4px}.pageid{font-size:10pt;color:#5e787c}h2{font-size:12pt;margin:12px 0 6px;break-after:avoid}p{margin:7px 0}.period{font-size:9pt;margin:8px 0}.period b{padding:0 10px}.notice{background:#fff5df;border-left:3px solid #bf893b;padding:8px 10px;font-size:8.5pt;margin:8px 0 12px}.tiles{display:table;table-layout:fixed;width:100%;border-spacing:7px 0;margin:12px 0}.tiles>div{display:table-cell;border:1px solid #d5e2de;background:#f4f8f6;border-radius:6px;padding:10px;vertical-align:top}.tiles small{font-size:8pt;display:block;min-height:22px}.tiles strong{font-size:20pt;display:block;margin:6px 0;white-space:normal}.tiles p{font-size:8pt;margin:0}table{width:100%;border-collapse:collapse;table-layout:fixed;margin:7px 0}thead{display:table-header-group}th{text-align:left;background:#eaf2ef;font-size:8.5pt;padding:8px;border:1px solid #cfded8}td{vertical-align:top;padding:8px;border:1px solid #d7e3de;font-size:9pt;overflow-wrap:anywhere;word-break:normal}td small{display:block;color:#5e787c;font-size:8pt;margin-top:4px}tr{break-inside:avoid;page-break-inside:avoid}.summaryline{background:#edf5f1;padding:9px;font-size:9pt;margin:10px 0}.method{font-size:8.5pt;color:#4f666b;line-height:1.4}footer{border-top:1px solid #d5e2de;padding-top:8px;margin-top:12px;font-size:7.5pt;color:#61777b}@media print{html,body{background:white;margin:0;padding:0;width:auto}.toolbar{display:none!important}.page{width:auto;min-height:0;margin:0;padding:0;box-shadow:none}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}@media print{body{font-size:8.8pt;line-height:1.25}header{padding-bottom:6px;margin-bottom:6px}.eyebrow{font-size:7pt}h1{font-size:16pt}h1 span{font-size:10pt}.pageid,.period{font-size:8pt}.notice{font-size:7.3pt;padding:6px 8px;margin:6px 0 8px}.tiles{margin:8px 0;border-spacing:5px 0}.tiles>div{padding:7px}.tiles small{font-size:7pt;min-height:17px}.tiles strong{font-size:18pt;margin:4px 0}.tiles p{font-size:7pt}h2{font-size:10pt;margin:8px 0 5px}table{margin:5px 0}th{font-size:8pt;padding:6px}td{font-size:8.6pt;padding:6px;line-height:1.25}td small{font-size:7pt;margin-top:3px}p{margin:5px 0}.summaryline{font-size:8pt;padding:7px;margin:7px 0}.method{font-size:7.4pt;line-height:1.25}footer{font-size:6.8pt;padding-top:6px;margin-top:7px}}@media screen and (max-width:900px){body{overflow-x:auto}.toolbar{min-width:700px}.page{margin:12px}}
</style></head><body><div class="toolbar"><span>Print-ready CEO report · A4 landscape · ${pages.length} designed pages</span><button onclick="window.print()">Print / Save as PDF</button></div>${pages.map(p=>'<section class="page">'+p+'</section>').join('')}</body></html>`}
root.createCeoReport=createCeoReport;if(typeof module!=='undefined')module.exports={createCeoReport};
})(typeof window==='undefined'?globalThis:window);
